/** Deterministic local-host projections of the preserved shared runtimes.
 * The two original files remain the maintained behavior sources. A changed
 * source hash requires a reviewed projection successor; generated files are
 * never edited by hand. No registry, descriptor, or admission state is read. */
import assert from 'node:assert/strict';
import {createHash} from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';

const repositoryRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const [mode, ...args] = process.argv.slice(2);
assert(['--write', '--check'].includes(mode), 'expected --write or --check');
let sourceRoot = repositoryRoot, outputRoot = repositoryRoot;
for (let index = 0; index < args.length; index += 2) {
  const option = args[index], value = args[index + 1];
  assert(value && ['--source-root', '--output-root'].includes(option), 'bounded path option');
  if (option === '--source-root') sourceRoot = path.resolve(value);
  else outputRoot = path.resolve(value);
}
const hash = bytes => createHash('sha256').update(bytes).digest('hex');
const sources = Object.freeze([
  Object.freeze({path: 'apps/web/components/animation-runtime.tsx', bytes: 57458,
    sha256: 'c21101c76c36cc8d062f832b2392491434c8e5c1ca0dc77edd24e233e0b74829'}),
  Object.freeze({path: 'apps/web/components/source-lesson-candidate-player-v1.generated.tsx', bytes: 55391,
    sha256: '4a9d1bdf3a0337ed74a295228d4620090e64ea233dba8b3eb9f9f7999467e660'}),
]);
function readSource(pin) {
  const bytes = fs.readFileSync(path.join(sourceRoot, pin.path));
  assert.equal(bytes.length, pin.bytes, `source size: ${pin.path}`);
  assert.equal(hash(bytes), pin.sha256, `source hash: ${pin.path}`);
  return bytes.toString('utf8');
}
function replaceExact(source, before, after, count = 1) {
  assert.equal(source.split(before).length - 1, count, `projection occurrence: ${before}`);
  return source.replaceAll(before, after);
}
const header = '// Generated by scripts/generate-source-lesson-loader-cores-v1.mjs; do not edit.\n';
const globalLoaderImport = "import {loadClientAnimationModule} from '@/lib/load-animation-module.client';\n";
let runtime = readSource(sources[0]);
runtime = replaceExact(runtime, globalLoaderImport, '');
runtime = replaceExact(runtime, 'export function AnimationRuntime({\n',
  'export function AnimationRuntimeCoreV1({\n  loadAnimationModule,\n');
runtime = replaceExact(runtime, '}: {\n  audioEnabled?: boolean;\n',
  '}: {\n  loadAnimationModule: (key: string) => Promise<AnimationModule | undefined>;\n  audioEnabled?: boolean;\n');
runtime = replaceExact(runtime, 'loadClientAnimationModule(moduleKey)', 'loadAnimationModule(moduleKey)');
runtime = replaceExact(runtime, '}, [moduleKey, typographyCapture]);',
  '}, [loadAnimationModule, moduleKey, typographyCapture]);');
runtime = header + runtime;

let player = readSource(sources[1]);
player = replaceExact(player, player.split('\n')[0] + '\n', header);
player = replaceExact(player, globalLoaderImport,
  "import type {AnimationModule} from '@helpmath/demos/animation-registry';\n");
player = replaceExact(player, '  AnimationRuntime,\n',
  '  AnimationRuntimeCoreV1 as AnimationRuntime,\n');
player = replaceExact(player, "} from '@/components/animation-runtime';",
  "} from '@/components/animation-runtime-loader-core-v1.generated';");
player = replaceExact(player, 'export function SourceLessonCandidatePlayerV1({\n',
  'export function SourceLessonCandidatePlayerCoreV1({\n  loadAnimationModule,\n');
player = replaceExact(player, '}: {\n  audioEnabled?: boolean;\n',
  '}: {\n  loadAnimationModule: (key: string) => Promise<AnimationModule | undefined>;\n  audioEnabled?: boolean;\n');
player = replaceExact(player, 'loadClientAnimationModule(nextModuleKey)', 'loadAnimationModule(nextModuleKey)');
player = replaceExact(player, '}, [nextModuleKey, runtimeAvailable]);',
  '}, [loadAnimationModule, nextModuleKey, runtimeAvailable]);');
player = replaceExact(player,
  'const RuntimeComponent:ComponentType<LessonRuntimeAdapterProps>=activeRuntimeAdapter?.Component ?? AnimationRuntime;',
  'const RuntimeComponent:ComponentType<LessonRuntimeAdapterProps>|typeof AnimationRuntime=activeRuntimeAdapter?.Component ?? AnimationRuntime;');
player = replaceExact(player, '    ? <RuntimeComponent\n',
  '    ? <RuntimeComponent\n        loadAnimationModule={loadAnimationModule}\n');

const outputs = [
  ['apps/web/components/animation-runtime-loader-core-v1.generated.tsx', runtime],
  ['apps/web/components/source-lesson-candidate-player-core-v1.generated.tsx', player],
];
for (const [relative, text] of outputs) {
  assert(!text.includes('loadClientAnimationModule'), 'no global loader symbol in core');
  assert(!text.includes('load-animation-module.client'), 'no global loader import in core');
  const filename = path.join(outputRoot, relative);
  if (mode === '--check') assert.equal(fs.readFileSync(filename, 'utf8'), text, `projection drift: ${relative}`);
  else if (fs.existsSync(filename)) assert.equal(fs.readFileSync(filename, 'utf8'), text, `refuse generated drift: ${relative}`);
  else {
    fs.mkdirSync(path.dirname(filename), {recursive: true});
    fs.writeFileSync(filename, text, {flag: 'wx'});
  }
}
console.log(JSON.stringify({kind: 'source-locked-local-host-loader-cores-v1', mode, sources,
  outputs: outputs.map(([relative, text]) => ({path: relative, bytes: Buffer.byteLength(text), sha256: hash(text)}))}));
